create extension if not exists pgcrypto;
create type public.account_type as enum ('dj','listener');
create type public.room_status as enum ('scheduled','live','paused','ended','cancelled');
create type public.rsvp_status as enum ('pending','approved','declined','waitlisted');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,account_type public.account_type not null default 'listener',display_name text not null check(length(display_name) between 1 and 80),username text unique check(username is null or username ~ '^[a-z0-9_-]{3,30}$'),avatar_url text,bio text check(bio is null or length(bio)<=500),location text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.dj_profiles(user_id uuid primary key references public.profiles(id) on delete cascade,genres text[] not null default '{}',booking_email text,is_public boolean not null default true);
create table public.follows(follower_id uuid references public.profiles(id) on delete cascade,dj_id uuid references public.dj_profiles(user_id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,dj_id),check(follower_id<>dj_id));
create table public.sets(id uuid primary key default gen_random_uuid(),dj_id uuid not null references public.dj_profiles(user_id) on delete cascade,title text not null check(length(title) between 1 and 120),description text,visibility text not null default 'private' check(visibility in('private','public')),status text not null default 'draft' check(status in('draft','published')),published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.tracks(id uuid primary key default gen_random_uuid(),set_id uuid not null references public.sets(id) on delete cascade,position integer not null check(position>0),title text not null,artist text not null,bpm numeric(6,2) check(bpm is null or bpm between 30 and 300),musical_key text,isrc text,source_url text,unique(set_id,position));
create table public.set_imports(id uuid primary key default gen_random_uuid(),dj_id uuid not null references public.dj_profiles(user_id) on delete cascade,source_format text not null check(source_format in('rekordbox_xml','serato_csv','virtualdj_m3u','traktor_nml')),original_filename text not null,status text not null default 'pending' check(status in('pending','parsed','failed','committed')),summary jsonb not null default '{}',created_at timestamptz default now());
create table public.music_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,provider text not null,status text not null default 'disconnected',scopes text[] not null default '{}',token_ciphertext text,expires_at timestamptz,updated_at timestamptz default now(),unique(user_id,provider));
create table public.live_rooms(id uuid primary key default gen_random_uuid(),dj_id uuid not null references public.dj_profiles(user_id) on delete cascade,title text not null,description text,status public.room_status default 'scheduled',current_track jsonb,starts_at timestamptz,ended_at timestamptz,created_at timestamptz default now());
create table public.room_participants(room_id uuid references public.live_rooms(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,joined_at timestamptz default now(),last_seen_at timestamptz default now(),primary key(room_id,user_id));
create table public.room_reactions(id uuid primary key default gen_random_uuid(),room_id uuid references public.live_rooms(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,reaction text not null,created_at timestamptz default now());
create table public.room_comments(id uuid primary key default gen_random_uuid(),room_id uuid references public.live_rooms(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,body text not null check(length(body) between 1 and 500),created_at timestamptz default now());
create table public.track_requests(id uuid primary key default gen_random_uuid(),room_id uuid references public.live_rooms(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,title text not null,artist text not null,status text default 'submitted',created_at timestamptz default now());
create table public.social_events(id uuid primary key default gen_random_uuid(),host_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text,starts_at timestamptz not null,ends_at timestamptz,location_label text not null,private_address text,capacity integer not null default 50 check(capacity between 1 and 500),visibility text not null default 'private',approval_required boolean not null default true,plus_ones_allowed boolean not null default false,song_suggestions_enabled boolean not null default true,created_at timestamptz default now(),check(ends_at is null or ends_at>starts_at));
create table public.invitations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.social_events(id) on delete cascade,token_hash text not null unique,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz default now());
create table public.event_guests(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.social_events(id) on delete cascade,user_id uuid references public.profiles(id) on delete set null,invitation_id uuid references public.invitations(id) on delete set null,display_name text not null,email text,phone text,status public.rsvp_status default 'pending',plus_one_count integer not null default 0 check(plus_one_count between 0 and 5),approved_at timestamptz,created_at timestamptz default now());
create unique index event_guest_user_unique on public.event_guests(event_id,user_id) where user_id is not null;
create table public.song_suggestions(id uuid primary key default gen_random_uuid(),event_id uuid references public.social_events(id) on delete cascade,guest_id uuid references public.event_guests(id) on delete cascade,title text not null,artist text not null,url text,status text default 'submitted',created_at timestamptz default now());
create table public.event_moments(id uuid primary key default gen_random_uuid(),event_id uuid references public.social_events(id) on delete cascade,guest_id uuid references public.event_guests(id) on delete cascade,storage_path text not null,caption text,status text default 'pending',created_at timestamptz default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,plan text not null,status text not null default 'pending',provider_reference text unique,current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz default now());
create table public.payments(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete restrict,subscription_id uuid references public.subscriptions(id) on delete set null,provider text not null default 'paystack',reference text not null unique,amount_minor bigint not null check(amount_minor>0),currency text not null default 'NGN',status text not null default 'initialized',provider_payload jsonb,created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,type text not null,title text not null,body text,read_at timestamptz,created_at timestamptz default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare t public.account_type; begin t:=case when new.raw_user_meta_data->>'account_type'='dj' then 'dj'::public.account_type else 'listener'::public.account_type end; insert into public.profiles(id,account_type,display_name,username) values(new.id,t,coalesce(nullif(left(new.raw_user_meta_data->>'display_name',80),''),'New member'),nullif(lower(left(new.raw_user_meta_data->>'username',30)),'')) on conflict(id) do nothing; if t='dj' then insert into public.dj_profiles(user_id) values(new.id) on conflict do nothing; end if; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.rsvp_to_event(p_event_id uuid,p_display_name text,p_email text default null,p_plus_ones integer default 0) returns public.event_guests language plpgsql security definer set search_path=public as $$ declare e public.social_events; g public.event_guests; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into e from public.social_events where id=p_event_id for update; if not found then raise exception 'Event not found'; end if; if p_plus_ones<0 or p_plus_ones>5 or (not e.plus_ones_allowed and p_plus_ones>0) then raise exception 'Invalid plus-one selection'; end if; if (select count(*) from public.event_guests where event_id=p_event_id and status='approved')+p_plus_ones>=e.capacity then raise exception 'Event is full'; end if; insert into public.event_guests(event_id,user_id,display_name,email,status,plus_one_count) values(p_event_id,auth.uid(),left(trim(p_display_name),80),p_email,case when e.approval_required then 'pending'::public.rsvp_status else 'approved'::public.rsvp_status end,p_plus_ones) on conflict(event_id,user_id) where user_id is not null do update set display_name=excluded.display_name,email=excluded.email,plus_one_count=excluded.plus_one_count returning * into g; return g; end $$;
do $$ declare t text; begin foreach t in array array['profiles','dj_profiles','follows','sets','tracks','set_imports','music_connections','live_rooms','room_participants','room_reactions','room_comments','track_requests','social_events','invitations','event_guests','song_suggestions','event_moments','subscriptions','payments','notifications','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profiles_read on public.profiles for select using(true);
create policy profiles_update on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy dj_public_read on public.dj_profiles for select using(is_public or auth.uid()=user_id);
create policy dj_owner_update on public.dj_profiles for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy follows_read on public.follows for select using(true);
create policy follows_insert on public.follows for insert with check(auth.uid()=follower_id);
create policy follows_delete on public.follows for delete using(auth.uid()=follower_id);
create policy sets_read on public.sets for select using((visibility='public' and status='published') or auth.uid()=dj_id);
create policy sets_insert on public.sets for insert with check(auth.uid()=dj_id);
create policy sets_update on public.sets for update using(auth.uid()=dj_id) with check(auth.uid()=dj_id);
create policy sets_delete on public.sets for delete using(auth.uid()=dj_id);
create policy tracks_read on public.tracks for select using(exists(select 1 from public.sets s where s.id=set_id and ((s.visibility='public' and s.status='published') or s.dj_id=auth.uid())));
create policy tracks_manage on public.tracks for all using(exists(select 1 from public.sets s where s.id=set_id and s.dj_id=auth.uid())) with check(exists(select 1 from public.sets s where s.id=set_id and s.dj_id=auth.uid()));
create policy imports_owner on public.set_imports for all using(auth.uid()=dj_id) with check(auth.uid()=dj_id);
create policy connections_owner on public.music_connections for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy rooms_read on public.live_rooms for select using(true);
create policy rooms_owner on public.live_rooms for all using(auth.uid()=dj_id) with check(auth.uid()=dj_id);
create policy participants_read on public.room_participants for select using(true);
create policy participants_self on public.room_participants for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy reactions_read on public.room_reactions for select using(true);
create policy reactions_self on public.room_reactions for insert with check(auth.uid()=user_id);
create policy comments_read on public.room_comments for select using(true);
create policy comments_self on public.room_comments for insert with check(auth.uid()=user_id);
create policy requests_read on public.track_requests for select using(true);
create policy requests_self on public.track_requests for insert with check(auth.uid()=user_id);
create policy events_read on public.social_events for select using(visibility='public' or auth.uid()=host_id);
create policy events_host on public.social_events for all using(auth.uid()=host_id) with check(auth.uid()=host_id);
create policy invitations_host on public.invitations for all using(exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid())) with check(exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid()));
create policy guests_read on public.event_guests for select using(auth.uid()=user_id or exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid()));
create policy guests_insert on public.event_guests for insert with check(auth.uid()=user_id);
create policy guests_update on public.event_guests for update using(exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid()));
create policy suggestions_read on public.song_suggestions for select using(exists(select 1 from public.event_guests g where g.id=guest_id and g.user_id=auth.uid()) or exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid()));
create policy moments_read on public.event_moments for select using(exists(select 1 from public.event_guests g where g.id=guest_id and g.user_id=auth.uid()) or exists(select 1 from public.social_events e where e.id=event_id and e.host_id=auth.uid()));
create policy subscriptions_owner_read on public.subscriptions for select using(auth.uid()=user_id);
create policy payments_owner_read on public.payments for select using(auth.uid()=user_id);
create policy notifications_owner on public.notifications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy audit_actor_read on public.audit_logs for select using(auth.uid()=actor_id);
grant execute on function public.rsvp_to_event(uuid,text,text,integer) to authenticated;
